---@alias gcp.baremetalsolution_v2.VolumeConfigProtocolEnum "PROTOCOL_UNSPECIFIED"|"PROTOCOL_FC"|"PROTOCOL_NFS"

---@alias gcp.baremetalsolution_v2.VolumeConfigTypeEnum "TYPE_UNSPECIFIED"|"FLASH"|"DISK"

---@alias gcp.baremetalsolution_v2.VolumeList gcp.baremetalsolution_v2.Volume[]

---@alias gcp.baremetalsolution_v2.VolumePerformanceTierEnum "VOLUME_PERFORMANCE_TIER_UNSPECIFIED"|"VOLUME_PERFORMANCE_TIER_SHARED"|"VOLUME_PERFORMANCE_TIER_ASSIGNED"|"VOLUME_PERFORMANCE_TIER_HT"|"VOLUME_PERFORMANCE_TIER_QOS2_PERFORMANCE"

---@alias gcp.baremetalsolution_v2.VolumeProtocolEnum "PROTOCOL_UNSPECIFIED"|"FIBRE_CHANNEL"|"NFS"

